CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, repo TEXT NOT NULL UNIQUE, remote TEXT NOT NULL, policy_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), task TEXT NOT NULL, principal TEXT NOT NULL, agent TEXT NOT NULL, scope_json TEXT NOT NULL, evidence_required_json TEXT NOT NULL, manifest_json TEXT NOT NULL, fork TEXT NOT NULL UNIQUE, remote TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS tasks_active ON tasks(project_id,state);
CREATE TABLE IF NOT EXISTS changes (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), repo TEXT NOT NULL, ref TEXT NOT NULL, manifest_json TEXT NOT NULL, evidence_state TEXT NOT NULL DEFAULT 'pending', state TEXT NOT NULL DEFAULT 'submitted', workflow_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS verdicts (id TEXT PRIMARY KEY, change_id TEXT NOT NULL REFERENCES changes(id), state TEXT NOT NULL, schema_json TEXT NOT NULL, probabilities_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS holds (id TEXT PRIMARY KEY, change_id TEXT NOT NULL REFERENCES changes(id), reason TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'open', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS receipts (id TEXT PRIMARY KEY, change_id TEXT NOT NULL REFERENCES changes(id), requirement TEXT NOT NULL, object_key TEXT NOT NULL, content_type TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(change_id,requirement));
CREATE TABLE IF NOT EXISTS workflow_steps (change_id TEXT NOT NULL REFERENCES changes(id), step TEXT NOT NULL, state TEXT NOT NULL, detail_json TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(change_id,step));
